917	
918	    let attributes: Vec<_> = element
919	        .opening_element()
920	        .ok()
921	        .into_iter()
922	        .flat_map(|opening| opening.attributes())
923	        .filter_map(|attr| {
924	            let html_attr = attr.as_html_attribute()?;
925	            let name = html_attr
926	                .name()
927	                .ok()?
928	                .value_token()
929	                .ok()?
930	                .token_text_trimmed();
931	            let value = html_attr
932	                .initializer()
933	                .and_then(|init| init.value().ok())
934	                .and_then(|v| v.as_html_string().cloned())
935	                .and_then(|s| s.inner_string_text().ok());
