940	    // Extract content from HtmlEmbeddedContent child
941	    let content_child = element.children().iter().next().and_then(|child| {
942	        let child = child.as_any_html_content()?;
943	        child.as_html_embedded_content().cloned()
944	    })?;
945	    let value_token = content_child.value_token().ok()?;
946	
947	    Some(EmbedCandidate::Element {
948	        tag_name,
949	        attributes,
950	        content: EmbedContent {
951	            element_range: content_child.range(),
952	            content_range: value_token.text_range(),
953	            content_offset: value_token.text_range().start(),
954	            // Use full token text (including trivia) to match the untrimmed content_offset.
955	            // The parser needs text and offset to be consistent.
956	            text: value_token.token_text(),
